#include "Metronome.h"
#include "PatternTools.h"
#include "ControlEdits.h"
static void testAppearance(const File& root,Assets& assets){
    auto source=demoProject();for(int i=0;i<(int)source.patterns.size();++i)source.patterns[(size_t)i].colour=i+1;
    Project loaded;expect(projectSchema==14&&projectFromJson(projectToJson(source),loaded).wasOk()&&JSON::toString(projectToJson(source))==JSON::toString(projectToJson(loaded)),"schema 14 preserves every pattern colour without changing note state");
    auto file=root.getChildFile("coloured-patterns.pulse");expect(saveProject(source,file).wasOk()&&loadProject(file,loaded).wasOk()&&loaded.patterns[0].colour==1,"pattern colours persist to native files");
    for(int schema=1;schema<=13;++schema){auto v=projectToJson(emptyProject());v.getDynamicObject()->setProperty("schema",schema);for(auto& p:*v["patterns"].getArray())p.getDynamicObject()->removeProperty("colour");expect(projectFromJson(v,loaded).wasOk()&&loaded.patterns[0].colour==0,"older project schemas migrate missing colour to Automatic");}
    auto before=JSON::toString(projectToJson(loaded));for(auto bad:{var(-1),var(13),var(1.5),var("3"),var(true),var()}){auto v=projectToJson(source);(*v["patterns"].getArray())[0].getDynamicObject()->setProperty("colour",bad);expect(projectFromJson(v,loaded).failed()&&JSON::toString(projectToJson(loaded))==before,"invalid persisted pattern colours fail atomically");}
    auto missing=projectToJson(source);(*missing["patterns"].getArray())[0].getDynamicObject()->removeProperty("colour");expect(projectFromJson(missing,loaded).failed(),"schema 14 requires explicit pattern colours");
    std::set<uint32_t> palette;for(int c=1;c<patternColourCount;++c)palette.insert(patternColourARGB(c));expect(palette.size()==12&&patternColourARGB(0)==0&&patternColourARGB(-1)==0&&patternColourName(12)=="Grey","pattern palette has twelve distinct colours and safe Automatic fallback");
    auto plain=source;for(auto& p:plain.patterns)p.colour=0;auto a=render(source,assets,root,8000),b=render(plain,assets,root,8000);expect(a==b,"pattern colour changes leave rendered music sample-exact");
    Project result;PatternEditStats stats;expect(makeClipPatternUnique(source,0,result).wasOk()&&result.patterns.back().colour==source.patterns[(size_t)source.clips[0].pattern].colour,"make unique inherits source colour");
    expect(splitPatternChannels(source,0,result,&stats).wasOk()&&std::all_of(stats.created.begin(),stats.created.end(),[&](int p){return result.patterns[(size_t)p].colour==source.patterns[0].colour;}),"every split channel inherits the original colour");
    expect(mergePatternLayers(source,0,1,result).wasOk()&&result.patterns.back().colour==source.patterns[0].colour,"layer merge inherits current pattern colour");
    expect(mergePatternSequence(source,0,1,result).wasOk()&&result.patterns.back().colour==source.patterns[0].colour,"sequential merge inherits current pattern colour");
    auto id=source.patterns[0].editorId;expect(movePattern(source,0,2,result).wasOk()&&result.patterns[2].editorId==id&&result.patterns[2].colour==1,"bank reordering carries colour with the pattern identity");
    expect(applyControlEdits(source,JSON::parse(R"([{"op":"set_pattern","pattern":0,"colour":12},{"op":"add_pattern","name":"Blue phrase","colour":5}])"),result).wasOk()&&result.patterns[0].colour==12&&result.patterns.back().colour==5,"MCP can colour existing and newly appended patterns");
    auto sentinel=JSON::toString(projectToJson(result));for(auto colour:{"-1","13","1.5","true","\"3\""}){auto ops=JSON::parse(String("[{\"op\":\"set_pattern\",\"pattern\":0,\"colour\":")+colour+"}]");expect(applyControlEdits(source,ops,result).failed()&&JSON::toString(projectToJson(result))==sentinel,"invalid MCP colours preserve the complete output candidate");}
    expect(applyControlEdits(source,JSON::parse(R"([{"op":"set_pattern","pattern":0,"name":"Retained colour"}])"),result).wasOk()&&result.patterns[0].colour==1,"omitted MCP colour retains the current setting");
    auto settingsFile=root.getChildFile("metronome-settings.json");MetronomeSettings settings{2,65,false},restored;expect(saveMetronome(settingsFile,settings).wasOk()&&loadMetronome(settingsFile,restored).wasOk()&&restored==settings,"metronome preferences save and restore atomically");
    auto stored=settingsFile.loadFileAsString();expect(saveMetronome(settingsFile,{4,201,true}).failed()&&settingsFile.loadFileAsString()==stored,"invalid metronome save preserves an existing preferences file");
    for(auto text:{"{}","{\"schema\":99,\"sound\":0,\"level\":100,\"accent\":true}","{\"schema\":1,\"sound\":4,\"level\":100,\"accent\":true}","{\"schema\":1,\"sound\":0,\"level\":-1,\"accent\":true}","{\"schema\":1,\"sound\":0,\"level\":201,\"accent\":true}","{\"schema\":1,\"sound\":0,\"level\":1.5,\"accent\":true}","{\"schema\":1,\"sound\":0,\"level\":100,\"accent\":1}"}){settingsFile.replaceWithText(text);auto keep=restored;expect(loadMetronome(settingsFile,restored).failed()&&restored==keep,"corrupt or mistyped metronome preferences retain the current settings");}
    settingsFile.replaceWithText(String::repeatedString("x",4097));expect(loadMetronome(settingsFile,restored).failed()&&restored==settings,"oversized metronome preferences are rejected");
    for(int sound=0;sound<metronomeSoundCount;++sound)for(int level:{0,1,50,100,200})for(bool accent:{false,true}){MetronomeSettings s{sound,level,accent};expect(unpackMetronome(packMetronome(s))==s,"atomic metronome configuration round-trips the valid settings");}
    std::set<uint64_t> clickHashes;
    for(int sound=0;sound<metronomeSoundCount;++sound)for(double rate:{8000.,44100.,48000.,96000.,192000.}){
        MetronomeClick first,second,half,muted,plainBeat;first.start(rate,true,{sound,100,true});second.start(rate,true,{sound,100,true});half.start(rate,true,{sound,50,true});muted.start(rate,true,{sound,0,true});plainBeat.start(rate,true,{sound,100,false});
        bool finite=true,deterministic=true,linear=true,silent=true,equalBeat=true;float peak=0;uint64_t hash=1469598103934665603ull;int count=(int)(rate*.024);
        MetronomeClick referenceBeat;referenceBeat.start(rate,false,{sound,100,true});
        for(int i=0;i<count+100;++i){float x=first.next(),y=second.next();finite&=std::isfinite(x)&&std::abs(x)<.4f;deterministic&=x==y;linear&=std::abs(half.next()*2-x)<.000001f;silent&=muted.next()==0;equalBeat&=plainBeat.next()==referenceBeat.next();peak=jmax(peak,std::abs(x));hash=(hash^(uint64_t)(int64_t)std::llround(x*1e8))*1099511628211ull;}
        expect(finite&&peak>.005f&&first.next()==0,"all click sounds have finite bounded audio and an exact short tail at every supported rate");expect(deterministic&&linear&&silent&&equalBeat,"click synthesis is deterministic, level-linear, muteable and obeys accent off");if(rate==48000)clickHashes.insert(hash);first.reset();expect(first.next()==0,"reset immediately clears click tails");
    }
    expect(clickHashes.size()==4,"four metronome sounds produce distinct audio");
    for(bool accent:{false,true}){MetronomeClick classic;classic.start(48000,accent,{});bool exact=true;int count=1152;for(int i=0;i<count;++i){float old=(float)(std::sin((count-i)*2*3.14159265358979323846*(accent?2200.f:1500.f)/48000)*(accent?.13f:.08f)*(count-i)/(48000*.024));exact&=classic.next()==old;}expect(exact,"default classic click is sample-exact with the previous release formula");}
    auto song=emptyProject();song.bpm=120;song.metronome=true;song.loop=false;auto e=makeEngine(song,assets,root);e->setMetronomeSettings({1,0,false});AudioBuffer<float> block(2,48000);e->render(block.getWritePointer(0),block.getWritePointer(1),48000);expect(block.getMagnitude(0,0,48000)==0&&e->position.load()>0,"zero metronome level silences live clicks without stopping transport");
    e=makeEngine(song,assets,root);e->setMetronomeSettings({2,75,false});expect(e->beginTake({0,0,-1,4}),"configured metronome can start a count-in");AudioBuffer<float> count(2,96000);e->render(count.getWritePointer(0),count.getWritePointer(1),96000);bool same=true;for(int beat=1;beat<4;++beat)for(int i=0;i<1152;++i)same&=count.getSample(0,i)==count.getSample(0,beat*24000+i);expect(same&&count.getMagnitude(0,0,1152)>.001f&&e->captureCount==0&&e->position.load()==0,"count-in shares the configured sound and equal-beat option without changing capture boundaries");
    auto renderConfigured=[&](int size){auto eng=makeEngine(song,assets,root);eng->setMetronomeSettings({3,63,true});AudioBuffer<float> audio(2,100000);for(int pos=0;pos<100000;pos+=size){int n=jmin(size,100000-pos);eng->render(audio.getWritePointer(0,pos),audio.getWritePointer(1,pos),n);}return audio;};
    expect(renderConfigured(127)==renderConfigured(512),"configured live metronome is sample-exact across callback sizes");
    e->stop();e->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(block.getMagnitude(0,0,512)==0,"Stop clears configured click tails");
    RenderSettings options;options.bits=32;options.tailSeconds=0;options.endBeat=1;auto exportFile=root.getChildFile("metronome-excluded.wav");
    expect(renderAudio(song,assets,root,exportFile,options).wasOk(),"native offline render accepts a song with its metronome enabled");
    AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(exportFile));AudioBuffer<float> exported(2,24000);exported.clear();if(reader)reader->read(&exported,0,24000,0,true,true);expect(reader&&exported.getMagnitude(0,0,24000)==0,"live metronome and count-in preferences never leak into offline exports");
}
